"""One delivery contract for initial generation, followers and manual regeneration."""
ROLES=(
 ('01_main','主图：准确展示本变体真实颜色、规格及销售数量；醒目的俄语大标题，旁边清晰罗列2—4条有事实依据的重要卖点，文字简洁、层级清晰、不遮挡商品'),
 ('02_dimensions','商品尺寸图：只采用商品尺寸，不能把包装尺寸写成商品尺寸；全组尺寸不同时明确标注对应选项'),
 ('03_scene','真实使用场景一：环境丰富、自然生活感，优先加入符合商品用途和目标受众的人物正在实际使用，展示明确的使用动作与商品价值'),
 ('04_scene','真实使用场景二：更换合理的空间、人物动作或用途，背景有生活细节；优先人物互动，不重复上一张布景'),
 ('05_material','材质细节：只描述已知主体和配件/内衬材质，局部特写与整体结合，不能混淆材质'),
 ('06_structure','结构展示：仅展示参考图及参数能证实的结构，不臆造折叠、拆装或承重功能'),
 ('07_details','重要细节和变体选择：真实细节特写，颜色/规格对比要清楚标注各选项，不暗示全部选项一起发货'),
 ('08_contents','套装实际内容：明确购买一个变体实际收到的件数、颜色和已知配件，不添加未声明配件'),
)

VISUAL_STYLE='视觉参考只借鉴构图、文字层级、留白和特写组织，不借用参考商品的外观、品牌或功能。采用真实商品摄影感，背景与品类/用途相符，优先柔和自然光和中性底色，商品与背景分离清楚；整组统一字体、圆角卡片、图标线条和留白。强调色少量取自实际商品或场景，不固定绿色，不改变变体真实颜色。俄文采用清晰粗体无衬线标题，通常1—2行，标题、卖点、补充说明形成三级层次，避免细小长段文字；手机缩略图中仍应能分清商品和标题。四周保留约5%安全边距，边框、尺寸箭头和文字不压住商品关键轮廓。无品牌商品不加品牌标、仿品牌椭圆徽章或PUREU字样；货号、SKU、任务编号、参考图文件名不得印进图内。'
MAIN_STYLE='【主图通用模板，仅作用于01主图，不改变02—08详情图的用途或设计要求】\n设计目标：手机缩略图先看清卖什么、商品真实样貌及最重要的购买理由；做一张完整俄语电商主图，不输出设计分析、候选版或额外海报。\n先根据本变体真实商品、用途、件数和已知卖点，只选择一种合适的构图：家具/家居用品用大主体搭配新设计的实际使用环境；小型配件/工具用放大的实物主体、简洁工作环境或摄影背景，配侧边信息；舒适体验/儿童用品可用自然人物实际使用，但人物不抢主体；多件套明确真实件数和商品单位，完整展示实际销售组合；技术类商品用清晰产品摄影和少量已知关键规格。不能把所有商品都放进同一种客厅或强行套统一信息栏。\n画面层级：先安排真实商品，主体视觉上占画面约三分之二，按形态灵活调整，完整保留关键轮廓、支架/腿脚及销售件数；再安排大标题和2—4条有事实依据的重要卖点，事实不足则减少。标题通常放上方或侧上方留白，约占画面高度15%—25%作为参考，不能为塞文字缩小、拉长或压扁商品。边缘留安全距离，信息卡不盖关键连接、功能部件和商品边界。\n标题样式：自然俄语，核心商品名称最大最醒目，修饰词次一级，优先1—2行；采用清晰粗体无衬线字体，整张最多两种协调字体，高对比配色，少量强调色与本品协调。长标题先删冗余形容词，不把文字缩成小字。缩略图仍能读出商品类别；不把内部货号、SKU、任务编号、文件名、广告口号堆进标题。\n卖点展现：按购买决策价值筛选，优先真实用途、可确认结构/材质、实际便利及明确关键规格；用2—4组简短词组搭配简洁图标、胶囊标签或少量信息卡，避免密集长段。仅将1—2个有依据且重要的数字放大，数字带准确单位；没有对应事实就不写。套装数量写清商品单位，场景里的桌子、床、杯子等道具不能被误认成随货套装。可选1—2个本品真实细节近景辅助说明，不能重复完整商品造成多件误判。\n原创场景：提供的风格样例只用于理解视觉层级、排版和信息组织；为当前商品重新设计适合其用途的空间、光线、镜头、配色和道具关系，不复刻样例的房间、家具组合、布景、人物姿势或机位。场景应有真实空间纵深、接触阴影和材质质感，陈设克制而有生活感，商品比背景更清楚。需要人物时，人物年龄/动作与真实用途相符，接触自然、比例正确，允许使用所必需的局部遮挡，但主体结构仍可辨认。没有适用依据，不用雪地、极端天气或特殊工况暗示性能。\n商品锁定与事实边界：只依照当前变体原始商品图和参数，优先保留实物抠图合成；准确保持外形、纹理、缝线、部件数量、支撑造型、颜色分区及件数，不从风格样例借用结构或功能。无品牌不加品牌/官方店标；不得搬用样例的承重、功率、节水率、适用年龄、质保、安全认证、抗过敏或护脊等宣称。道具不冒充赠品或配件，不增加未声明坐垫、装置、屏幕、图案或包装。生成前自检商品一致、文案有依据、字体易读、数量无误、场景原创；只交付当前约定的最终主图文件。'
EVIDENCE_STYLE='参考中的条绒、纽扣、旋转底座、泡沫按压和人物姿态均不是本商品事实：原商品是平绒就不能变成条绒，原图没有纽扣/扶手/旋转机构就不能增加。材质名称以已提供参数和本品原图为准，不能把вельвет与велюр混为一谈。旋转、透气、承重、护脊、久坐不累、长久不变形等宣传必须有明确事实依据；无法证实则不写。只有填充材料已明确时才可说明填充，不用通用泡沫切面图冒充实物内部，不凭渲染效果声称经过测试。人物按压只展示可确认的本品表面交互，不夸张改变坐垫厚度或形状。'
POSTER_RULE='不做把多张完整海报缩成一页的整套拼图或联系表；允许一张独立海报内使用局部特写、信息卡和尺寸标注，局部窗口仍是本张用途的辅助说明，不算额外交付图片。'
LAYOUTS={
 '02_dimensions':'表现优化：使用本品可确认的完整视角，商品尺寸箭头清晰，数字和单位易读，避免装饰盖住测量端点；不从总尺寸推算座高/座深等未提供尺寸。',
 '03_scene':'表现优化：一个清晰的实际使用动作配丰富但不杂乱的真实环境；人物服装、动作、人与商品比例自然，保留足够商品结构可见。',
 '04_scene':'表现优化：保留第二使用场景用途，切换空间或明确使用动作，不能仅给上一张换背景颜色；通过少量陈设体现生活感，不把道具写成随货配件。',
 '05_material':'表现优化：本品整体或足够识别的主体配1—3个真实材质局部特写，整体和特写的纹理、颜色、针脚必须一致；材质短标题加简短解释，不改变本图材质用途。',
 '06_structure':'表现优化：保持结构展示用途，完整结构视角配连接/支撑部位的真实近景，必要时用简洁引线；不替换为泡沫宣传图，不画无依据的拆解、剖面或旋转箭头。',
 '07_details':'表现优化：保持重要细节与变体选择用途，按已提供的对应原图做细节和选项标签，各颜色/规格明确分组；不能把不同变体的部件拼成一个新款，也不能暗示全部颜色一起发货。',
 '08_contents':'表现优化：保持实际套装内容用途，简洁背景逐项展示一个所选变体实际收到的商品/已知配件，突出真实数量；不加入场景道具，不用重复特写充当多件实物。',
}

def role_layout(name,brief):return brief+('；'+LAYOUTS[name] if name in LAYOUTS else '')

def generation_prompt(facts,group_facts='',expected=8):
 if expected not in (1,8):raise ValueError('图片交付数量只能为1或8')
 common='每张3:4竖版，自然俄语排版，风格统一。严格保持参考图对应变体的外形、颜色、比例和结构。不得虚构参数、认证、承重、防水或功能；卖点不足时减少文字，不编造补足。涉及人物时，人手、姿势、商品使用方式和尺寸比例应合理，人物与商品实际接触自然；允许真实坐姿等必要局部遮挡，但商品仍清楚可辨，关键轮廓、底座或支撑结构可见，不把主体大面积藏住。'
 if expected==1:
  contract='本任务只能生成和交付1张最终主图，不生成其他图片；文件名固定01_main.jpg。主图要求：'+ROLES[0][1]+'。后7张详情图由本地沿用首变体，不要重复生成。'
 else:
  contract='本任务只能交付8张最终独立图片，必须严格按01到08逐张生成并按该顺序交付；不要多出第9张，不提供额外封面、试稿、备选图或重复版本，不把整套海报拼成一张交付。需要修改时只将最终定稿纳入交付，不把过程图混入成品列表。固定顺序与用途：'+'；'.join(name+'.jpg：'+role_layout(name,brief) for name,brief in ROLES)+'。02—08为全组共用详情，涉及颜色或尺寸差异必须标注选项；无法兼容的细节不写成全组通用。'
 return contract+common+VISUAL_STYLE+EVIDENCE_STYLE+POSTER_RULE+MAIN_STYLE+FIDELITY+'最终只列出本次'+str(expected)+'张对应编号的独立文件及逐张下载入口，文件数量必须与编号一一对应，不要打包，不提供ZIP。当前变体商品事实：'+facts+('。当前主图只依据本变体资料，其他变体不得作为外观依据：'+facts if expected==1 else '。同组全部变体资料：'+(group_facts or facts))

FIDELITY='商品一致性优先于设计美化：只能使用本次附件中该变体的原始商品参考图作为外观依据，禁止沿用历史对话、其他变体或AI生成图中的商品。优先保留原商品并抠图合成，只改背景和排版，不重新设计或替换成相似款。逐项保持真实轮廓、比例、表面纹理/缝线、靠背与座面形状、腿脚/支架数量和造型、扶手有无、连接结构及颜色分区；原图没有的扶手、脚轮、配件不得增加。参考图看不到的角度沿用可确认视角，不凭空补画隐藏结构。每套件数必须与当前变体参数一致。俄语标题与真实卖点放在留白区，不能为排版压缩或改变商品。'

def shared_prompt(group_facts):
 roles=ROLES[1:]
 return '本任务只重做全组共用的7张详情图，不生成主图、不改任何变体主图。严格交付7张独立3:4竖版JPG，文件按本任务01—07编号，分别对应商品详情位置02—08，不混入第8张或过程图，不把整套海报合成一张，不提供ZIP。用途顺序：'+'；'.join('%02d_%s.jpg：%s'%(i+1,name.split('_',1)[1],role_layout(name,brief)) for i,(name,brief) in enumerate(roles))+'。7张图各自的用途和顺序固定，视觉参考不能改变这些用途。统一自然俄语排版；人物互动重点用于原定的两张使用场景图，不把每一张都变成人物广告。涉及不同颜色、规格、材质或件数必须分别标注选项，不能混装或将不同结构写成全组通用。'+VISUAL_STYLE+EVIDENCE_STYLE+POSTER_RULE+FIDELITY+'未附对应原图的变体只作已知参数的文字说明，不凭空绘制该选项的商品外观。最终仅提供这7个编号文件的逐张下载入口。全组事实：'+group_facts

def reference_contract(task):
 refs=task.get('references') or [];lines=[]
 for i,r in enumerate(refs):
  usage=('对应变体在共用详情中的真实商品外观' if r.get('purpose','variant_main')=='variant_main' else '全组共用细节依据，差异不可写成通用') if task.get('kind')=='shared_details' else ('仅用于本变体主图外观' if r.get('purpose','variant_main')=='variant_main' else '只作共用详情依据，不作为本变体主图外观')
  lines.append(str(i+1)+'：'+str(r.get('name','原图'))+'；货号 '+str(r.get('sku') or task.get('sku',''))+'；用途 '+usage)
 return FIDELITY+'\n本次附件对应关系：\n'+'\n'.join(lines)
